// Use pre-bundled station data for Cloudflare Workers compatibility
// This is generated by scripts/build-station-data-optimized.js
import {stationsLookup, timeModified} from './bundled-data/db-stations.js'

// Convert the pre-built lookup map to the expected format
// The bundled data already has all lookups (id, ril100, additionalIds) pre-computed
const pStations = Promise.resolve({
	data: stationsLookup,
	timeModified: timeModified
})

pStations.catch((err) => {
	console.error('Error loading stations:', err)
	// Note: In Cloudflare Workers, errors should be handled gracefully
	// rather than exiting the process
})

export {
	pStations,
}
